"""policy-briefing: builds dashboards, Power BI files, and docs from anonymized sample data.
python src/build.py"""
import sys, re, glob, warnings
from pathlib import Path
import numpy as np, pandas as pd
warnings.filterwarnings("ignore")
ROOT = Path(__file__).resolve().parents[1]; PROC = ROOT / "data" / "processed"; sys.path.insert(0, str(Path(__file__).parent))
from scaffold import Project, PALETTE
D9, D4, NL, IL = "Region A sample snapshot 9-Feb-2026", "Region A sample snapshot 4-Feb-2026", "review sub-committee sample 4-Dec-2025", "sample issue-list workbook"

rd = lambda n: pd.read_csv(PROC / n)
sc, pg, ms, dr, ig, cmp, cmps, cn = [rd(n) for n in ["statea_scorecard.csv", "statea_progress_timeline.csv", "milestones.csv", "policy_directions.csv", "integrations.csv", "statea_vs_stateb.csv", "statea_vs_stateb_scale.csv", "concept_note.csv"]]
S = dict(zip(sc.metric, sc.value))
P = Project(ROOT, "policy-briefing", "Policy Briefing: Cooperative Services Sample",
            "An anonymized sample briefing for policy and program leaders: scorecard, progress timeline, generalized actions, integrations, and comparisons between anonymized regions.",
            banner="Anonymized sample data: labels are pseudonyms and metrics are rescaled illustrations, not operational results.",
            footer="Sample data only. Do not use these figures for operational decisions.")
kp = lambda n, v, f, d, dax, src, aud, **kw: P.kpi(n, v, f, d, "As reported", dax, src, aud, **kw)
m = lambda name: f'CALCULATE(SUM(statea_scorecard[value]), statea_scorecard[metric] = "{name}")'
k1 = kp("e-PACS achieved", S["e-PACS achieved"], "pct2", "Share of PACS working in e-PACS mode (9-Feb-2026 sample)", m("e-PACS achieved"), D9, "policy lead, policy briefing, development finance partner", tone="good", home=True)
k2 = kp("ERP onboarding", S["ERP onboarding"], "int", "PACS onboarded on the ERP", m("ERP onboarding"), D9, "policy briefing, development finance partner", home=True)
k3 = kp("Audit and YEP FY2024-25", S["Audit and YEP FY2024-25 completed"], "int", "PACS with audit and year-end completed for 2024-25", m("Audit and YEP FY2024-25 completed"), D9, "policy briefing, cooperative registrar", note="of all PACS", home=True)
k4 = P.kpi("Ticket resolution rate", 100 * S["Tickets resolved"] / S["Tickets raised"], "pct2", "Tickets resolved as share of tickets raised", "Resolved / Raised", f'DIVIDE({m("Tickets resolved")}, {m("Tickets raised")})', IL, "policy briefing, development finance partner", tone="good", home=True)
k5 = P.kpi("Enhancements completed", 100 * S["Enhancements completed"] / S["Enhancement requests raised"], "pct1", "Completed enhancement requests as share of requests raised", "Completed / Raised", f'DIVIDE({m("Enhancements completed")}, {m("Enhancement requests raised")})', D9, "state-level banking partner, development finance partner, policy briefing", note=f"{int(S['Enhancements completed'])} of {int(S['Enhancement requests raised'])}", home=True)
k6 = kp("PACS identified for reorganisation", S["PACS identified for reorganisation"], "int", "PACS identified for bifurcation or reorganisation", m("PACS identified for reorganisation"), D4, "policy lead, cooperative registrar")
k7 = kp("Integrations requested", S["Integrations requested"], "int", "Portal integrations requested from Vendor", m("Integrations requested"), NL, "policy briefing, development finance partner")
k8 = kp("Support centres", S["District support centres"], "int", "District-level support centres (plus the state command centre)", m("District support centres"), D4, "policy briefing, development finance partner")
k9 = P.kpi("Directions tracked", len(dr), "int", "Directions under review", "Count of directions", "COUNTROWS(policy_directions)", "Record of discussion", "policy briefing")
for n, d, ds, g in [("statea_scorecard", sc, "State scorecard metrics with date and source", "metric"), ("statea_progress_timeline", pg, "e-PACS progress at dated points (definitions differ by source)", "date x measure"), ("milestones", ms, "Review milestones and deadlines", "event"), ("policy_directions", dr, "policy briefing directions of 28-Jan-2026 with State A evidence", "direction"),
                    ("integrations", ig, "Portal integrations and status", "integration"), ("statea_vs_stateb", cmp, "State A vs State B progress, same metric", "metric"), ("statea_vs_stateb_scale", cmps, "State A vs State B scale", "metric"), ("concept_note", cn, "Concept Note requirements by module and theme", "requirement")]: P.table(n, d, ds, g)
P.relationships = ["All tables are independent; no relationships are required.", "Use `statea_scorecard[metric]` as a slicer or filter to pick KPI cards.", "`concept_note[module]` and `concept_note[theme]` are the axes for the enhancement charts."]
P.sources = [("Programme review decks (PowerPoint)", "Scorecard, enhancements, support, reorganisation"), ("Committee review deck", "Integrations and customization status"), ("State review decks", "Dated e-PACS progress"), ("Ticket counter workbook", "Ticket counters"), ("state-level banking partner letter and record of discussion", "Progress at a date, national directions"), ("State SOP letter", "Deadlines and daily reporting rules"), ("Neighbouring-state comparison deck", "Comparison metrics"), ("Requirement note (Excel)", "Enhancement requirements")]

P.exclusions = ["Real district, branch and bank names (replaced by pseudonyms).", "Original source files, PACS-level extracts, names, contact details and credentials.", "Real counts: all counts are rescaled, so absolute numbers are illustrative."]

P.assumptions = ["Scorecard values are transcribed from slides and then rescaled for this edition.", "Progress points use each source's own definition (completed, certificates, reported) and must not be read as one continuous series.", "The comparison state deck is undated, so metrics are matched by name, not by date.", "Customization counts differ between sources; the tracker is used."]

P.page("scorecard", "Sample scorecard", "Illustrative position on cooperative-service rollout measures.", [
    {"type": "kpis", "items": [k1, k2, k3, k4, k5, k6]},
    {"type": "hbars", "title": "PACS covered by each milestone (of all PACS)", "w": "half", "src": "statea_scorecard", "rows": [dict(label=n, value=int(S[n])) for n in ["PACS sanctioned", "DCT onboarding", "ERP onboarding", "Audit and YEP FY2023-24 completed", "Audit and YEP FY2024-25 completed", "T-7 entry model", "SMS gateway active"]], "color": "var(--c1)", "max": int(S["PACS sanctioned"])},
    {"type": "line", "title": "e-PACS progress as reported (% of PACS)", "w": "half", "src": "statea_progress_timeline", "labels": [d[2:] for d in sorted(pg.date.unique())], "series": [dict(name=g, values=[(float(x.pct.iloc[0]) if len(x) else None) for d in sorted(pg.date.unique()) for x in [pg[(pg.group == g) & (pg.date == d)]]], color=PALETTE[i]) for i, g in enumerate(pg.group.unique())], "max": 100, "note": "One line per definition: the sources do not measure the same thing, so do not read across lines."},
    {"type": "table", "title": "Scorecard with sources", "src": "statea_scorecard", "cols": [dict(key="metric", label="Metric"), dict(key="value", label="Value", fmt="num"), dict(key="unit", label="Unit"), dict(key="as_of", label="As of"), dict(key="source", label="Source")], "rows": sc.to_dict("records"), "sort": "as_of"}], tags=["Minister", "policy briefing", "development finance partner"])
P.page("directions", "Sample directions tracker", "Generalized sample actions and their recorded evidence.", [
    {"type": "kpis", "items": [k9, dict(label="Directions tracked", value=str(len(dr))), dict(label="Next customization deadline", value="15-Feb-2026")]},
    {"type": "table", "title": "Directions and State A evidence", "src": "policy_directions", "cols": [dict(key="area", label="Area"), dict(key="direction", label="Direction"), dict(key="deadline", label="Deadline"), dict(key="owner", label="Owner"), dict(key="statea_evidence", label="State A evidence")], "rows": dr.to_dict("records"), "sort": "no", "dir": 1}], tags=["policy briefing", "cooperative registrar"])
th = cn.theme.value_counts(); mo = cn.module.value_counts()
P.page("integrations", "Integrations and enhancements", "Portal integrations with their status, and the Concept Note enhancement requirements by theme and module.", [
    {"type": "kpis", "items": [k7, k5, dict(label="Concept Note requirements", value=str(len(cn)))]},
    {"type": "stacks", "title": "Integration requests (4-Dec-2025)", "w": "half", "src": "statea_scorecard", "groups": [dict(name="12 requested", parts=[dict(label=l, value=int(S[n]), color=PALETTE[i]) for i, (l, n) in enumerate([("On hold until e-PACS", "Integrations on hold until e-PACS mode"), ("Pending at Vendor", "Integrations pending at Vendor"), ("Pending at State", "Integrations pending at State"), ("Pending at development finance partner", "Integrations pending at development finance partner")])])]},
    {"type": "stack", "title": "Enhancement requests (9-Feb-2026)", "w": "half", "src": "statea_scorecard", "parts": [dict(label="Completed", value=int(S["Enhancements completed"]), color=PALETTE[4]), dict(label="Open", value=int(S["Enhancement requests raised"] - S["Enhancements completed"]), color=PALETTE[2])]},
    {"type": "hbars", "title": "Concept Note by theme", "w": "half", "src": "concept_note", "rows": [dict(label=k, value=int(v)) for k, v in th.items()], "color": "var(--c4)"},
    {"type": "hbars", "title": "Concept Note by module", "w": "half", "src": "concept_note", "rows": [dict(label=k, value=int(v)) for k, v in mo.head(10).items()]},
    {"type": "table", "title": "Portal integrations", "src": "integrations", "cols": [dict(key="integration", label="Integration"), dict(key="purpose", label="Purpose"), dict(key="status", label="Status")], "rows": ig.to_dict("records"), "sort": "integration", "dir": 1},
    {"type": "table", "title": "Concept Note requirements", "src": "concept_note", "search": "module", "maxh": 420, "cols": [dict(key="sno", label="#", fmt="int"), dict(key="module", label="Module"), dict(key="theme", label="Theme"), dict(key="enhancement", label="Required enhancement")], "rows": cn.to_dict("records"), "sort": "sno", "dir": 1}], tags=["Vendor", "state-level banking partner", "policy briefing"])
P.page("state-comparison", "Region A and Region B", "Comparable sample progress measures as a share of the anonymized population in scope.", [
    {"type": "kpis", "items": [dict(label="State A PACS in scope", value=f"{int(cmps.state_a[1]):,}"), dict(label="State B PACS in scope", value=f"{int(cmps.state_b[1]):,}"), dict(label="Support centres State A / State B", value=f"{int(cmps.state_a[0])} / {int(cmps.state_b[0])}")]},
    {"type": "stacks", "title": "Share of PACS reached (%)", "w": "half", "src": "statea_vs_stateb", "groups": [dict(name=r.metric, parts=[dict(label=f"State A {r.statea_pct:.0f}%", value=r.statea_pct, color=PALETTE[0]), dict(label=f"State B {r.stateb_pct:.0f}%", value=r.stateb_pct, color=PALETTE[1])]) for r in cmp.itertuples()]},
    {"type": "table", "title": "State A vs State B", "w": "half", "src": "statea_vs_stateb", "cols": [dict(key="metric", label="Metric"), dict(key="statea_pct", label="State A %", fmt="pct1"), dict(key="stateb_pct", label="State B %", fmt="pct1"), dict(key="source", label="Source")], "rows": cmp.to_dict("records"), "sort": "statea_pct"}], tags=["policy briefing", "development finance partner"])
P.page("milestones", "Milestones and deadlines", "Review dates, letters and deadlines on one timeline, plus the daily and monthly records the e-PACS SOP requires.", [
    {"type": "table", "title": "Timeline", "src": "milestones", "cols": [dict(key="date", label="Date"), dict(key="event", label="Event"), dict(key="source", label="Source")], "rows": ms.to_dict("records"), "sort": "date", "dir": 1},
    {"type": "text", "title": "Records required under the e-PACS SOP", "w": "half", "html": "<ul class='clean'><li><b>Daily:</b> voucher files, Day Book / Cash Book, Receipts and Payments, Trial Balance (before and after day-end)</li><li><b>Daily soft copy, monthly hard copy:</b> Stock Register</li><li><b>Monthly:</b> head-wise General Ledger</li><li><b>Monthly, within 5 days:</b> module closing balances (share, loan, deposit, PDS, merchandise, borrowing, investment), reconciled to the General Ledger and Trial Balance</li></ul>", "note": "Source: cooperative registrar letter of 13-Jan-2026 and Annexure 1."},
    {"type": "text", "title": "Online working rule", "w": "half", "html": "<p style='margin:0'>PACS must post transactions on the ERP in real time and not enter them after a manual process. Branches reconcile DMR adjustments within one working day, based only on ERP-generated reports. A compliance certificate (Annexure 3) is sent by the Deputy / Assistant Commissioner and the district cooperative bank CEO until every PACS is online.</p>"}], tags=["cooperative registrar", "district cooperative bank"])
P.build()
